import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

const KycDetails = () => {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    aadhaar: {
      aadhaarNumber: "",
      name: "",
      dateOfBirth: ""
    },
    pan: {
      panNumber: "",
      name: "",
      document: ""
    }
  });

  // Load existing KYC data
  useEffect(() => {
    fetch("http://localhost:5000/userProfile")
      .then((response) => response.json())
      .then((data) => {
        if (data.kycDetails) {
          setFormData(data.kycDetails);
        }
      })
      .catch((error) => console.log(error));
  }, []);

  const handleAadhaarChange = (e) => {
    setFormData({
      ...formData,
      aadhaar: {
        ...formData.aadhaar,
        [e.target.name]: e.target.value
      }
    });
  };

  const handlePanChange = (e) => {
    setFormData({
      ...formData,
      pan: {
        ...formData.pan,
        [e.target.name]: e.target.value
      }
    });
  };

  const handleSave = () => {
    fetch("http://localhost:5000/userProfile", {
      method: "PATCH",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        kycDetails: formData
      })
    })
      .then((response) => response.json())
      .then(() => {
        alert("KYC details saved successfully");
        navigate("/gst-details");
      })
      .catch((error) => {
        console.log(error);
        alert("Error saving KYC details");
      });
  };

  return (
    <div className="form-card">
      <div className="form-header">
        <h2>Aadhaar & PAN Details</h2>
        <p>Enter your Aadhaar and PAN details</p>
      </div>

      <div className="kyc-cards">

        {/* Aadhaar */}
        <div className="kyc-card">
          <h3>Aadhaar Details</h3>

          <div className="form-group">
            <label>Aadhaar Number</label>
            <input
              type="text"
              name="aadhaarNumber"
              placeholder="Enter Aadhaar number"
              maxLength="12"
              value={formData.aadhaar.aadhaarNumber}
              onChange={handleAadhaarChange}
            />
          </div>

          <div className="form-group">
            <label>Name as per Aadhaar</label>
            <input
              type="text"
              name="name"
              placeholder="Enter name"
              value={formData.aadhaar.name}
              onChange={handleAadhaarChange}
            />
          </div>

          <div className="form-group">
            <label>Date of Birth</label>
            <input
              type="date"
              name="dateOfBirth"
              value={formData.aadhaar.dateOfBirth}
              onChange={handleAadhaarChange}
            />
          </div>
        </div>

        {/* PAN */}
        <div className="kyc-card">
          <h3>PAN Details</h3>

          <div className="form-group">
            <label>PAN Number</label>
            <input
              type="text"
              name="panNumber"
              placeholder="Enter PAN number"
              maxLength="10"
              value={formData.pan.panNumber}
              onChange={handlePanChange}
            />
          </div>

          <div className="form-group">
            <label>Name as per PAN</label>
            <input
              type="text"
              name="name"
              placeholder="Enter name"
              value={formData.pan.name}
              onChange={handlePanChange}
            />
          </div>

          <div className="form-group">
            <label>PAN Document</label>
            <input
              type="file"
              onChange={(e) =>
                setFormData({
                  ...formData,
                  pan: {
                    ...formData.pan,
                    document: e.target.files[0]?.name || ""
                  }
                })
              }
            />
          </div>
        </div>

      </div>

      <div className="form-footer">
        <button
          className="save-button"
          onClick={handleSave}
        >
          Save KYC Details
        </button>
      </div>
    </div>
  );
};

export default KycDetails;
